<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Support contact form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #090d16;
        --panel: #111827;
        --panel-strong: #172033;
        --text: #f8fafc;
        --muted: #b6c2d6;
        --accent: #7dd3fc;
        --accent-strong: #38bdf8;
        --error: #fca5a5;
        --success: #86efac;
        --border: #334155;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        display: grid;
        place-items: center;
        padding: 2rem;
        background:
          radial-gradient(circle at top left, rgba(56, 189, 248, 0.16), transparent 34rem),
          linear-gradient(135deg, #050816 0%, var(--bg) 48%, #101827 100%);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      main {
        width: min(100%, 38rem);
      }

      .card {
        padding: clamp(1.5rem, 5vw, 2.5rem);
        border: 1px solid rgba(148, 163, 184, 0.24);
        border-radius: 1.5rem;
        background: linear-gradient(160deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.92));
        box-shadow: var(--shadow);
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(2rem, 7vw, 3.25rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .intro {
        margin: 0 0 2rem;
        color: var(--muted);
        font-size: 1.05rem;
      }

      .required-note {
        margin: 0 0 1.25rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .form-field {
        margin-bottom: 1.15rem;
      }

      label {
        display: block;
        margin-bottom: 0.45rem;
        font-weight: 700;
      }

      .required-marker {
        color: var(--accent);
        font-weight: 800;
      }

      input {
        width: 100%;
        min-height: 3.25rem;
        border: 1px solid var(--border);
        border-radius: 0.9rem;
        padding: 0.85rem 1rem;
        background: var(--panel-strong);
        color: var(--text);
        font: inherit;
        transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
      }

      input::placeholder {
        color: #8291a8;
        opacity: 1;
      }

      input:hover {
        border-color: #5b6f8f;
      }

      input:focus-visible,
      button:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: 3px;
      }

      input[aria-invalid="true"] {
        border-color: var(--error);
        box-shadow: 0 0 0 3px rgba(252, 165, 165, 0.16);
      }

      .help-text,
      .error-message {
        margin: 0.45rem 0 0;
        font-size: 0.92rem;
      }

      .help-text {
        color: var(--muted);
      }

      .error-message {
        color: var(--error);
        font-weight: 650;
      }

      .error-message:empty {
        display: none;
      }

      button {
        width: 100%;
        min-height: 3.25rem;
        margin-top: 0.4rem;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.25rem;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        color: #082f49;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        box-shadow: 0 16px 40px rgba(56, 189, 248, 0.22);
      }

      button:hover {
        filter: brightness(1.05);
      }

      button:active {
        transform: translateY(1px);
      }

      .form-status {
        min-height: 1.5rem;
        margin: 1rem 0 0;
        color: var(--success);
        font-weight: 700;
      }

      @media (max-width: 30rem) {
        body {
          padding: 1rem;
          place-items: start center;
        }

        .card {
          border-radius: 1.1rem;
        }
      }

      @media (forced-colors: active) {
        .card,
        input,
        button {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
        }

        .required-marker,
        .help-text,
        .error-message,
        .form-status {
          color: CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <main>
      <section class="card" aria-labelledby="support-title">
        <h1 id="support-title">Contact support</h1>
        <p class="intro">Tell us how to reach you and our support team will follow up as soon as possible.</p>

        <form id="support-form" novalidate>
          <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>

          <div class="form-field">
            <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
            <input id="full-name" name="full-name" type="text" autocomplete="name" required>
            <p class="error-message" id="full-name-error"></p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required-marker" aria-hidden="true">*</span></label>
            <input id="email-address" name="email-address" type="email" autocomplete="email" required>
            <p class="error-message" id="email-address-error"></p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number (optional)</label>
            <input id="phone-number" name="phone-number" type="tel" autocomplete="tel" aria-describedby="phone-number-help">
            <p class="help-text" id="phone-number-help">Use a 10-digit number, including area code, such as 555-123-4567.</p>
          </div>

          <button type="submit">Send support request</button>
          <p class="form-status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#support-form");
      const statusMessage = document.querySelector("#form-status");
      const fields = [
        {
          input: document.querySelector("#full-name"),
          error: document.querySelector("#full-name-error"),
          message: "Error: Enter your full name."
        },
        {
          input: document.querySelector("#email-address"),
          error: document.querySelector("#email-address-error"),
          message: "Error: Enter a valid email address, such as name@example.com."
        }
      ];

      function showError(field) {
        field.input.setAttribute("aria-invalid", "true");
        field.input.setAttribute("aria-describedby", field.error.id);
        field.error.textContent = field.message;
      }

      function clearError(field) {
        field.input.removeAttribute("aria-invalid");
        field.input.removeAttribute("aria-describedby");
        field.error.textContent = "";
      }

      fields.forEach((field) => {
        field.input.addEventListener("input", () => {
          if (field.input.validity.valid) {
            clearError(field);
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        statusMessage.textContent = "";

        const firstInvalidField = fields.find((field) => {
          if (!field.input.validity.valid) {
            showError(field);
            return true;
          }

          clearError(field);
          return false;
        });

        if (firstInvalidField) {
          firstInvalidField.input.focus();
          return;
        }

        statusMessage.textContent = "Thanks. Your support request is ready to send.";
        form.reset();
      });
    </script>
  </body>
</html>
