       @media (max-width: 30rem) {
         body {
           padding: 1rem;
           place-items: start center;
         }

         .card {
           border-radius: 1.1rem;
         }
       }

       @media (forced-colors: active) {
         .card,
         input,
         button {
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         button {
           background: ButtonFace;
           color: ButtonText;
         }

         .required-marker,
         .help-text,
         .error-message,
         .form-status {
           color: CanvasText;
         }
       }
     </style>
   </head>
   <body>
     <main>
       <section class="card" aria-labelledby="support-title">
         <h1 id="support-title">Contact support</h1>
         <p class="intro">Tell us how to reach you and our support team will follow up as soon as possible.</p>

         <form id="support-form" novalidate>
           <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>

           <div class="form-field">
             <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
             <input id="full-name" name="full-name" type="text" autocomplete="name" required>
             <p class="error-message" id="full-name-error"></p>
           </div>

           <div class="form-field">
             <label for="email-address">Email address <span class="required-marker" aria-hidden="true">*</span></label>
             <input id="email-address" name="email-address" type="email" autocomplete="email" required>
             <p class="error-message" id="email-address-error"></p>
           </div>

           <div class="form-field">
             <label for="phone-number">Phone number (optional)</label>
             <input id="phone-number" name="phone-number" type="tel" autocomplete="tel" aria-describedby="phone-number-help">
             <p class="help-text" id="phone-number-help">Use a 10-digit number, including area code, such as 555-123-4567.</p>
           </div>

           <button type="submit">Send support request</button>
           <p class="form-status" id="form-status" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#support-form");
       const statusMessage = document.querySelector("#form-status");
       const fields = [
         {
           input: document.querySelector("#full-name"),
           error: document.querySelector("#full-name-error"),
           message: "Error: Enter your full name."
         },
         {
           input: document.querySelector("#email-address"),
           error: document.querySelector("#email-address-error"),
           message: "Error: Enter a valid email address, such as name@example.com."
         }
       ];

       function showError(field) {
         field.input.setAttribute("aria-invalid", "true");
         field.input.setAttribute("aria-describedby", field.error.id);
         field.error.textContent = field.message;
       }

       function clearError(field) {
         field.input.removeAttribute("aria-invalid");
         field.input.removeAttribute("aria-describedby");
         field.error.textContent = "";
       }

       fields.forEach((field) => {
         field.input.addEventListener("input", () => {
           if (field.input.validity.valid) {
             clearError(field);
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         statusMessage.textContent = "";

         const firstInvalidField = fields.find((field) => {
           if (!field.input.validity.valid) {
             showError(field);
             return true;
           }

           clearError(field);
           return false;
         });

         if (firstInvalidField) {
           firstInvalidField.input.focus();
           return;
         }

         statusMessage.textContent = "Thanks. Your support request is ready to send.";
         form.reset();
       });
     </script>
   </body>
 </html>

