const axe = require('axe-core');

(async () => {
  const htmlPath = '/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-vanilla-js--style-dark--validation-message-absent/gpt-5.5__s2/index.html';
  const browser = await chromium.launch();
