    };
  }

  const initial = await runAxe('initial');
  await page.locator('button[type="submit"]').click();
  await page.waitForTimeout(100);
  const invalidSubmit = await runAxe('invalid-submit');
  await browser.close();

  const results = [initial, invalidSubmit];
  console.log(JSON.stringify(results, null, 2));
  if (results.some((result) => result.wcag.length > 0)) {
    process.exit(1);
  }
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
